def add(a: int, b: int) -> int:
    """Adds two integer numbers together.

    Parameters:
    a (int): The first number to be added.
    b (int): The second number to be added.

    Returns:
    int: The sum of the two numbers.
    """
    if not isinstance(a, int):
        raise TypeError(f"Expected 'a' to be int, got {type(a).__name__}")
    if not isinstance(b, int):
        raise TypeError(f"Expected 'b' to be int, got {type(b).__name__}")
    try:
        return a + b
    except Exception as e:
        raise RuntimeError("Error adding numbers") from e

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        ValueError: If n is negative or the length of coeffs does not match n+1.
        TypeError: If coeffs contains non-integer elements or n is not an integer.
    """
    # Validate input types
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if not isinstance(coeffs, list):
        raise TypeError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length must be {n + 1} for degree {n}")
    for c in coeffs:
        if not isinstance(c, int):
            raise TypeError("All coefficients must be integers")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = "-" if coeff < 0 else ""
        else:
            sign = "-" if coeff < 0 else "+"

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            if abs_coeff == 1:
                coeff_str = ""
            else:
                coeff_str = str(abs_coeff)

        # Determine variable part
        if degree == 0:
            var_str = ""
        elif degree == 1:
            var_str = "x"
        else:
            var_str = f"x^{degree}"

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return "0"

    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic type checks
    if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
        return "Failed"

    # Encoded and original must be of same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse = {}

    for e, o in zip(encoded, original):
        # Check for contradictions in mapping
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

        # Check for contradictions in reverse mapping
        if o in reverse:
            if reverse[o] != e:
                return "Failed"
        else:
            reverse[o] = e

    # Ensure mapping covers all 26 letters
    if len(mapping) != 26 or len(reverse) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    Args:
        x0 (int): The GCD that each pair (P, Q) must have.
        y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
        int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    # Validate inputs
    if not isinstance(x0, int) or not isinstance(y0, int):
        raise TypeError("x0 and y0 must be integers")
    if x0 <= 0 or y0 <= 0:
        raise ValueError("x0 and y0 must be positive integers")
    if y0 % x0 != 0:
        return 0

    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(n ** 0.5)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps if possible, otherwise "NO ANSWER!".
    """
    # Input validation
    if not isinstance(A, str) or not isinstance(B, str):
        raise TypeError("A and B must be strings.")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list.")
    for rule in rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise ValueError("Each rule must be a tuple of two strings.")
        src, tgt = rule
        if not isinstance(src, str) or not isinstance(tgt, str):
            raise ValueError("Rule elements must be strings.")

    # Quick check
    if A == B:
        return 0

    max_depth = 10
    queue = [(A, 0)]
    visited = {A}

    while queue:
        current, steps = queue.pop(0)
        if steps >= max_depth:
            continue
        next_steps = steps + 1
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_steps
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_steps))
                start = idx + 1  # allow overlapping replacements
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic type validation
    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set) or not all(isinstance(x, str) for x in liar_count):
        raise TypeError("liar_count must be a set of strings")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dictionary")
    if not isinstance(days_of_week, set) or not all(isinstance(x, str) for x in days_of_week):
        raise TypeError("days_of_week must be a set of strings")

    # Normalize days_of_week to upper case for case-insensitive matching
    days_upper = {day.upper() for day in days_of_week}

    for participant, stmts in statements.items():
        if not isinstance(participant, str):
            raise TypeError("participant names must be strings")
        if not isinstance(stmts, list):
            raise TypeError("statements for each participant must be a list")
        is_liar = participant in liar_count
        for stmt in stmts:
            if not isinstance(stmt, str):
                raise TypeError("each statement must be a string")
            # Skip statements that mention a day of the week
            stmt_upper = stmt.upper()
            if any(day in stmt_upper for day in days_upper):
                continue

            # Determine truth value of the statement
            truth = None
            stmt_clean = stmt.strip().rstrip('.').strip()
            # Handle "I am guilty." or "I am not guilty."
            if stmt_clean.lower().startswith("i am "):
                rest = stmt_clean[5:].strip().lower()
                if rest == "guilty":
                    truth = (participant == scenario)
                elif rest == "not guilty":
                    truth = (participant != scenario)
            # Handle "NAME is guilty." or "NAME is not guilty."
            else:
                # Look for pattern "<subject> is guilty" or "<subject> is not guilty"
                parts = stmt_clean.split(" is ", 1)
                if len(parts) == 2:
                    subject = parts[0].strip()
                    rest = parts[1].strip().lower()
                    if rest == "guilty":
                        truth = (subject == scenario)
                    elif rest == "not guilty":
                        truth = (subject != scenario)

            # If we couldn't parse the statement, ignore it
            if truth is None:
                continue

            # Check consistency with liar status
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False

    return True

def max_herb_value(T: int, M: int, herbs: list[tuple[int, int]]) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
    - T (int): The total time available for picking herbs.
    - M (int): The number of different herbs in the cave.
    - herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
      representing the time required to pick the herb and the herb's value, respectively.

    Returns:
    - int: The maximum total value of herbs that can be picked within the time limit.
    """
    # Basic input validation
    if not isinstance(T, int) or T < 0:
        raise ValueError("T must be a non-negative integer")
    if not isinstance(M, int) or M < 0:
        raise ValueError("M must be a non-negative integer")
    if not isinstance(herbs, list):
        raise ValueError("herbs must be a list of tuples")
    if len(herbs) != M:
        raise ValueError("Length of herbs list does not match M")

    for idx, h in enumerate(herbs):
        if not isinstance(h, tuple) or len(h) != 2:
            raise ValueError(f"herb at index {idx} is not a tuple of length 2")
        time_cost, value = h
        if not isinstance(time_cost, int) or time_cost < 0:
            raise ValueError(f"Time cost of herb at index {idx} must be a non-negative integer")
        if not isinstance(value, int):
            raise ValueError(f"Value of herb at index {idx} must be an integer")

    # DP array where dp[t] is the maximum value achievable with time limit t
    dp = [0] * (T + 1)

    for time_cost, value in herbs:
        # Iterate backwards to avoid using the same herb multiple times
        for t in range(T, time_cost - 1, -1):
            new_val = dp[t - time_cost] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return dp[T] if T >= 0 else 0

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n == 0:
        return 0

    # Ensure all elements are comparable (int or float)
    for h in heights:
        if not isinstance(h, (int, float)):
            raise ValueError("All heights must be numeric")

    # Compute LIS ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute LDS starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum removals
    return n - max_bitonic
